package mz.bam.seeky.android;
import android.content.*;import android.widget.*;import java.util.*;import org.json.*;

public final class SummaryActivity extends WorkspaceActivity {
    String id;int page;String title(){return "Resumo por etapas";}
    void load(){id=getIntent().getStringExtra("job");if(id==null){finish();return;}PlusUi.run(this,()->{StudyStore.Row job;List<StudyStore.Row> rows;long done,total;try(TaskStore db=new TaskStore(this)){job=db.job(id);rows=db.items(id,null,page*10,11);done=db.count(id,"done");total=db.count(id,null);}if(job==null)throw new java.io.IOException("Resumo indisponível.");PlusUi.post(this,()->{content.removeAllViews();note(job.s("title")+" · "+done+" / "+total+"\n"+job.s("message"));action("Abrir tarefas",()->TaskService.open(this));for(int n=0;n<Math.min(rows.size(),10);n++){StudyStore.Row item=rows.get(n);row("document",item.s("name"),item.s("state").equals("done")?AudioTitles.limit(item.s("message"),500,1500):item.s("message"),()->options(job,item));}pager(page,rows.size()>10,()->{page--;load();},()->{page++;load();});});});}
    void options(StudyStore.Row job,StudyStore.Row item){UiPanel panel=new UiPanel(this,item.s("name"),null,"document");if(item.s("state").equals("done")){panel.action("document","Ler resumo",null,false,()->new UiDialog.Builder(this).setTitle(item.s("name")).setMessage(item.s("message")).setPositiveButton("Fechar",null).show());panel.action("edit","Editar resumo guardado",null,false,()->{EditText edit=PlusUi.input(this,"Resumo",item.s("message"),20000);edit.setMinLines(8);new UiDialog.Builder(this).setTitle("Editar resumo guardado").setView(edit).setPositiveButton("Guardar",(d,w)->{String answer=edit.getText().toString().trim();if(answer.isEmpty()){PlusUi.toast(this,"O resumo está vazio.");return;}PlusUi.run(this,()->{try(TaskStore db=new TaskStore(this)){db.item(id,(int)item.n("seq"),StudyStore.values("message",answer));}try(StudyStore books=new StudyStore(this)){String tag="Seeky resumo "+id+"_"+item.n("seq");List<StudyStore.Row> notes=books.rows("notes","tags=?",new String[]{tag},null,1);if(!notes.isEmpty()){StudyStore.Row note=notes.get(0);String old=note.s("body"),footer=old.contains("\n\n"+AppLanguage.text(this,"Fonte")+":")?old.substring(old.indexOf("\n\n"+AppLanguage.text(this,"Fonte")+":")):"";books.save("notes",note.id(),StudyStore.values("body",answer+footer,"updated",System.currentTimeMillis()));}}StudyEvents.changed();PlusUi.post(this,this::load);});}).setNegativeButton("Cancelar",null).show();});}
        panel.action("book","Ver trecho de origem",null,false,()->PlusUi.run(this,()->{String source=SummaryWork.text(this,id,item);PlusUi.post(this,()->new UiDialog.Builder(this).setTitle(item.s("name")).setMessage(source).setPositiveButton("Fechar",null).setNeutralButton("Abrir origem",(d,w)->{try{JSONObject data=new JSONObject(job.s("payload"));startActivity(new Intent(this,ReaderActivity.class).setDataAndType(android.net.Uri.parse(data.getString("uri")),data.getString("mime")).putExtra("name",data.getString("name")).putExtra("study_material",data.optLong("material")).putExtra("study_segment",(int)item.n("part")).putExtra("search_offset",(int)item.n("position")).putExtra("search_length",1));}catch(Exception e){PlusUi.error(this,e);}}).show());}));
        if(Arrays.asList("uncertain","sent","failed").contains(item.s("state")))panel.action("refresh","Repetir este pedido",null,false,()->new UiDialog.Builder(this).setTitle("Repetir pedido à IA?").setMessage("Um pedido interrompido pode já ter consumido quota. Esta opção envia novamente apenas este trecho.").setPositiveButton("Repetir",(d,w)->PlusUi.run(this,()->{try(TaskStore db=new TaskStore(this)){db.item(id,(int)item.n("seq"),StudyStore.values("state","pending","message",""));}PlusUi.post(this,()->TaskService.start(this,id));})).setNegativeButton("Cancelar",null).show());panel.show();}
}
